// Дополнительные ограничения для пересечений по смыслу, а не по словам.
const SUBJECTS = { RU: [['transsiberian'], ['baikal']], AR: [['tango'], ['patagonia']], FI: [['sauna'], ['polar-light']], KR: [['starcraft'], ['hangul']], KP: [['mass-games'], ['dmz']], JM: [['reggae'], ['caribbean']], TR: [[], [], ['ataturk']], NZ: [['peter-jackson']] };
export function editorialFacts(id, locale) {
  return (FACT_PAIRS[id] || []).map(([topic, ru, en], i) => ({ text: locale === 'en' ? en : ru, topic, subjects: SUBJECTS[id]?.[i] || [] }));
}
export function editorialPerson(id, locale) {
  const p = PERSON_ROSTER[id];
  return p ? [p[locale === 'en' ? 2 : 0], p[locale === 'en' ? 3 : 1], p[4]] : null;
}
